package com.autoops.dataset.controller;import com.autoops.dataset.entity.DatasetImport;import com.autoops.dataset.repository.DatasetImportRepository;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/api/admin/datasets")public class DatasetController{private final DatasetImportRepository repo;public DatasetController(DatasetImportRepository r){repo=r;}@GetMapping public List<DatasetImport> list(){return repo.findAll();}@PostMapping public DatasetImport register(@RequestBody DatasetImport d){d.setUploadedBy(1L);d.setStatus("UPLOADED");return repo.save(d);}}
